"""Owner-only JRA PDF link discovery UI; no official PDF content parsing."""
HTML = "<section id=\"officialPdfSection\"><h2>3. JRA公式出馬表PDFの公開状況</h2><p class=\"hint\">日付を選んでボタンを押した時だけ、JRA公式の「開催場別出馬表」ページからPDFへのリンクを1回確認します。PDFの内容や馬番は読み取りません。</p><button type=\"button\" id=\"checkOfficialPdf\">選択日の公式出馬表PDFを探す</button><p id=\"officialPdfMessage\" role=\"status\" class=\"hint\">未確認。公式PDFが公開されても、出走取消・当日の変更は別途確認が必要やで。</p><div id=\"officialPdfLinks\"></div><p class=\"hint\">JRA公式リンクを開いて馬番を確認したら、下の照合欄へ入力してな。PDFリンク未掲載でも「開催中止」「出馬表未公開」とは断定しません。</p></section>"
CSS = "#officialPdfLinks a{display:block;margin:8px 0;padding:10px 12px;border:1px solid #577594;border-radius:10px}#officialPdfSection button:disabled{opacity:.5}"
JS = "'use strict';\n// Check official JRA listing links by explicit owner request, no OCR,\n// PDF download, horse data transfer, race-number verification, or betting.\n(function(){\n const $=id=>document.getElementById(id);\n const button=$('checkOfficialPdf'),picker=$('chooseMeeting'),\n       status=$('officialPdfMessage'),container=$('officialPdfLinks');\n let version=0,busy=false;\n function reset(){\n  version+=1;\n  container.replaceChildren();\n  button.disabled=false;\n  status.textContent='この日のJRA PDFリンクはまだ確認してへんで。';\n }\n const previous=picker.onchange;\n picker.onchange=()=>{if(typeof previous==='function')previous();reset();};\n button.onclick=async()=>{\n  const id=picker.value;\n  const date=id.split('|')[0];\n  if(!/^\\d{4}-\\d{2}-\\d{2}$/.test(date)||!id.includes('|')){\n   status.textContent='先に取り込み済みの開催日を選んでな。';return;\n  }\n  if(busy)return;\n  busy=true;button.disabled=true;\n  const requestVersion=++version;\n  container.replaceChildren();\n  status.textContent=date+'のJRA公式PDFリンクだけを照会中…';\n  try{\n   const result=await fetch('/api/jra/official-pdf-links?date='+encodeURIComponent(date),{\n    credentials:'same-origin',cache:'no-store',\n    headers:{'X-Keiba-Request':'private'}\n   });\n   const data=await result.json();\n   if(requestVersion!==version||picker.value!==id)return;\n   if(!result.ok)throw Error(data.error||'JRAの公開ページを確認できませんでした。');\n   if(data.version!=='jra-official-pdf-link-discovery-1'||\n      data.date!==date||data.indexUrl!=='https://www.jra.go.jp/keiba/rpdf/'||\n      data.pdfContentsRead!==false||data.officialRunnerNumbersVerified!==false||\n      data.entryChangeVerified!==false||data.predictionReady!==false||\n      data.bettingReady!==false||!Array.isArray(data.links)||data.links.length>10||\n      data.linkFound!==(data.links.length>0))\n    throw Error('公式PDFリンクの応答形式を確認できませんでした。');\n   const tracks=new Set();\n   for(const item of data.links){\n    if(!item||typeof item.track!=='string'||tracks.has(item.track)||\n       !['札幌','函館','福島','新潟','東京','中山','中京','京都','阪神','小倉'].includes(item.track))\n     throw Error('公式PDFの競馬場が不正です。');\n    tracks.add(item.track);\n    const u=new URL(item.url);\n    if(u.protocol!=='https:'||\n       !['www.jra.go.jp','jra.jp'].includes(u.hostname)||\n       !u.pathname.startsWith('/keiba/rpdf/')||\n       !u.pathname.toLowerCase().endsWith('.pdf')||\n       u.search||u.hash||u.username||u.password)\n     throw Error('公式サイト以外のリンクは表示しません。');\n   }\n   const notice=document.createElement('p');\n   notice.textContent=data.links.length?\n    'JRA公式ページに'+data.links.length+'競馬場分のPDFリンクを検出。PDF内の馬番は未解析やで。':\n    '指定日のPDFリンクは検出できず。未掲載か、ページの形式変更・取得遅延の可能性があるで。';\n   container.append(notice);\n   for(const item of data.links){\n    const a=document.createElement('a');\n    a.textContent=date+' '+item.track+'｜JRA公式の出馬表PDFを開く';\n    a.href=item.url;a.target='_blank';a.rel='noopener noreferrer';\n    container.append(a);\n   }\n   status.textContent='公式PDFのリンク確認完了。馬番・取消・馬場の自動照合は未実施。';\n  }catch(err){\n   if(requestVersion===version&&picker.value===id)\n    status.textContent=err&&err.message||'JRAの公開ページを確認できませんでした。';\n  }finally{busy=false;button.disabled=false;}\n };\n})();\n"
